import{_ as t,o as a,c as r,a5 as i}from"./chunks/framework.CslsFoWx.js";const m=JSON.parse(`{"title":"Plan d'action terrain — réglementaire & paiements","description":"","frontmatter":{},"headers":[],"relativePath":"commercial/actions-terrain.md","filePath":"generated/commercial/actions-terrain.md","lastUpdated":null}`),o={name:"commercial/actions-terrain.md"};function n(s,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><h1 id="plan-d-action-terrain-—-reglementaire-paiements" tabindex="-1">Plan d&#39;action terrain — réglementaire &amp; paiements <a class="header-anchor" href="#plan-d-action-terrain-—-reglementaire-paiements" aria-label="Permalink to &quot;Plan d&#39;action terrain — réglementaire &amp; paiements&quot;">​</a></h1><blockquote><p>Recherches du 28/10/2026 · Détail sourcé : scratchpad des agents (synthétisé ici). Textes juridiques tunisiens déjà récupérés : <a href="./legal/"><code>legal/</code></a> (arrêté du 14/10/2025, décret 2019-1126, art. 48 LF2016).</p></blockquote><h2 id="_1-cahier-des-charges-nacef-tunisie-—-🔴-bloquant-go-to-market-tn" tabindex="-1">1. Cahier des charges NACEF (Tunisie) — 🔴 bloquant go-to-market TN <a class="header-anchor" href="#_1-cahier-des-charges-nacef-tunisie-—-🔴-bloquant-go-to-market-tn" aria-label="Permalink to &quot;1. Cahier des charges NACEF (Tunisie) — 🔴 bloquant go-to-market TN&quot;">​</a></h2><h3 id="ce-qu-on-sait-deja-acquis" tabindex="-1">Ce qu&#39;on sait déjà (acquis) <a class="header-anchor" href="#ce-qu-on-sait-deja-acquis" aria-label="Permalink to &quot;Ce qu&#39;on sait déjà (acquis)&quot;">​</a></h3><ul><li>✅ <strong>L&#39;arrêté du 14/10/2025 (JORT n° 125) est récupéré</strong> → <code>legal/arrete-14Oct25.pdf</code>. Il fixe le calendrier (01/11/2025 → 01/07/2028) mais <strong>pas</strong> les specs techniques.</li><li>✅ Décret 2019-1126 et art. 48 LF2016 récupérés également.</li><li>❌ Le « Cahier des charges techniques et fonctionnelles » n&#39;est <strong>pas public</strong> : téléchargeable uniquement après <strong>inscription comme fournisseur</strong> sur <code>homologation.nacef.tn/fr/registerprovider</code>, lui-même accessible <strong>uniquement depuis une connexion réellement tunisienne</strong> (vérifié le 28/10 : tous les sites .tn hébergés en Tunisie — IP 41.225.7.x — coupent le TLS depuis l&#39;étranger ; un VPN « Tunisie » à localisation virtuelle ne marche PAS).</li></ul><h3 id="actions-dans-l-ordre" tabindex="-1">Actions (dans l&#39;ordre) <a class="header-anchor" href="#actions-dans-l-ordre" aria-label="Permalink to &quot;Actions (dans l&#39;ordre)&quot;">​</a></h3><ol><li><strong>Faire faire l&#39;inscription fournisseur depuis la Tunisie</strong> (proche sur place, ou toi-même lors d&#39;un passage) : <code>homologation.nacef.tn/fr/registerprovider</code> → télécharger le cahier des charges + le manuel des procédures. Alternative technique : louer un <strong>VPS chez un hébergeur tunisien</strong> et y faire transiter la connexion (voie durable pour les tests d&#39;intégration NACEF à venir).</li><li><strong>Appeler la DGI</strong> pour demander l&#39;envoi du document et le processus éditeur : <ul><li><strong>+216 81 100 400</strong> — Centre d&#39;Information Fiscale</li><li><strong>+216 71 780 347</strong> — cellule DGI</li><li>Responsable cité dans la presse : M. Mohamed Naqqach, directeur des applications informatiques, ministère des Finances.</li></ul></li><li><strong>Plan B</strong> : en obtenir copie auprès d&#39;un fournisseur déjà accrédité (ex. ASM — asmpos.com) ou d&#39;un confrère éditeur tunisien.</li><li>Une fois le document obtenu : <strong>réviser la spec 15</strong> (règles RG-FISC-30→38 marquées provisoires) et valider l&#39;hypothèse « module logiciel vs carte matérielle ».</li></ol><h3 id="modele-d-email-script-d-appel-dgi" tabindex="-1">Modèle d&#39;email / script d&#39;appel (DGI) <a class="header-anchor" href="#modele-d-email-script-d-appel-dgi" aria-label="Permalink to &quot;Modèle d&#39;email / script d&#39;appel (DGI)&quot;">​</a></h3><blockquote><p>Objet : Demande du cahier des charges — homologation NACEF (éditeur de logiciel de caisse)</p><p>Madame, Monsieur,</p><p>Je suis éditeur d&#39;un logiciel de caisse (solution SaaS multi-commerces, fonctionnement hors-ligne, applications iOS/Android) en cours de développement, et je souhaite engager la démarche d&#39;homologation NACEF.</p><p>Pourriez-vous me transmettre le cahier des charges techniques et fonctionnelles ainsi que le manuel des procédures d&#39;homologation, et me préciser les frais et délais du processus, ainsi que le calendrier des tests d&#39;intégration ?</p><p>[Si inscription déjà faite : mon identifiant fournisseur est …]</p><p>Cordialement, [nom, société, téléphone]</p></blockquote><h2 id="_2-paiements-tunisie-—-konnect-d-abord-flouci-en-parallele" tabindex="-1">2. Paiements Tunisie — Konnect d&#39;abord, Flouci en parallèle <a class="header-anchor" href="#_2-paiements-tunisie-—-konnect-d-abord-flouci-en-parallele" aria-label="Permalink to &quot;2. Paiements Tunisie — Konnect d&#39;abord, Flouci en parallèle&quot;">​</a></h2><h3 id="decisions-d-architecture-rappel-specs-03-09" tabindex="-1">Décisions d&#39;architecture (rappel specs 03/09) <a class="header-anchor" href="#decisions-d-architecture-rappel-specs-03-09" aria-label="Permalink to &quot;Décisions d&#39;architecture (rappel specs 03/09)&quot;">​</a></h3><ul><li>Modèle <strong>« intégrateur »</strong> : chaque marchand ouvre SON compte chez le provider — le POS orchestre, <strong>n&#39;encaisse jamais les fonds</strong> pour le compte des marchands. ⚠️ Encaisser pour autrui = établissement de paiement (loi 2016-48, capital minimum 5 M TND, agrément BCT) — à ne pas franchir sans avis juridique.</li></ul><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ol><li><strong>Konnect</strong> (démarrage immédiat, self-service) : <ul><li>Sandbox : <code>dashboard.sandbox.konnect.network</code> → créer un compte, générer la clé API</li><li>Frais publiés : 0 % cartes tunisiennes / 2,9 % internationales</li><li>Contact : contact@konnect.network + Discord développeurs</li></ul></li><li><strong>Flouci</strong> (QR wallet — différenciateur caisse/kiosque) : <ul><li>Sandbox immédiat (TEST APP automatique à l&#39;inscription développeur)</li><li><strong>Clé « QR Code Payments » sur demande</strong> : email à <strong><a href="mailto:dev-support@flouci.com" target="_blank" rel="noreferrer">dev-support@flouci.com</a></strong> (copie <strong><a href="mailto:sales@flouci.com" target="_blank" rel="noreferrer">sales@flouci.com</a></strong>) — go-live après KYB, 2–10 jours</li></ul></li><li><strong>Paymee</strong> (option de repli) : sandbox libre <code>sandbox.paymee.tn/panoramix/signup</code>, <a href="mailto:business@paymee.com.tn" target="_blank" rel="noreferrer">business@paymee.com.tn</a>, +216 55 220 221</li><li>France (pour mémoire, phase 2-3) : pas d&#39;agrément nécessaire pour l&#39;éditeur — intégration TPE via PSP (Stripe Terminal, SumUp, Adyen) ou protocole caisse-TPE.</li></ol><h3 id="modele-d-email-flouci" tabindex="-1">Modèle d&#39;email (Flouci) <a class="header-anchor" href="#modele-d-email-flouci" aria-label="Permalink to &quot;Modèle d&#39;email (Flouci)&quot;">​</a></h3><blockquote><p>Objet : Partenariat éditeur POS — accès API QR Code Payments</p><p>Bonjour,</p><p>Nous développons un logiciel de caisse SaaS (multi-commerces : restaurants, cafés, épiceries…) avec applications iOS/Android, kiosque self-service et fonctionnement hors-ligne, destiné au marché tunisien.</p><p>Nous souhaitons intégrer Flouci comme moyen de paiement à l&#39;encaissement (QR dynamique affiché en caisse et sur kiosque). Chaque commerçant disposerait de son propre compte marchand Flouci ; notre rôle est l&#39;intégration technique.</p><p>Pourriez-vous nous accorder l&#39;accès à l&#39;API QR Code Payments (clé partenaire) et nous indiquer le processus de convention/KYB pour nos marchands ?</p><p>Nous avons déjà testé votre sandbox. Disponible pour un appel.</p><p>Cordialement, [nom, société]</p></blockquote><h2 id="_3-plateforme-agreee-pa-—-e-reporting-france" tabindex="-1">3. Plateforme agréée (PA) — e-reporting France <a class="header-anchor" href="#_3-plateforme-agreee-pa-—-e-reporting-france" aria-label="Permalink to &quot;3. Plateforme agréée (PA) — e-reporting France&quot;">​</a></h2><h3 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h3><ul><li>155 PA immatriculées (+9 en attente) au 14/10/2026 — liste officielle : impots.gouv.fr « je-consulte-la-liste-des-plateformes-agreees »</li><li>Modèle retenu : <strong>OD (nous) + PA partenaire en marque blanche</strong> — devenir PA soi-même est exclu (coût/délai).</li><li>⚠️ Les clients <strong>GE/ETI sont DÉJÀ en obligation depuis le 01/09/2026</strong> ; PME/micro au 01/09/2027.</li></ul><h3 id="shortlist-detail-comparatif-dans-le-rapport-d-etude" tabindex="-1">Shortlist (détail comparatif dans le rapport d&#39;étude) <a class="header-anchor" href="#shortlist-detail-comparatif-dans-le-rapport-d-etude" aria-label="Permalink to &quot;Shortlist (détail comparatif dans le rapport d&#39;étude)&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><strong>iopole</strong> (PA principale recommandée)</th><th><strong>B2Brouter</strong> (challenger/secours)</th></tr></thead><tbody><tr><td>Positionnement</td><td>API-first, pensée pour les éditeurs (B2B2B marque blanche)</td><td>Meilleure doc développeur publique (guide DGFiP dédié)</td></tr><tr><td>E-reporting B2C</td><td>Intégré</td><td>Supporté, staging connecté au QAS</td></tr><tr><td>Sandbox</td><td>Gratuite</td><td>Oui</td></tr><tr><td>Tarifs</td><td>Sur devis partenaire</td><td>Partiellement publiés : 110–300 € HT/an/entreprise</td></tr><tr><td>Conflit commercial</td><td>Aucun avec un POS</td><td>Aucun</td></tr></tbody></table><h3 id="actions-1" tabindex="-1">Actions <a class="header-anchor" href="#actions-1" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><ol><li><strong>Maintenant</strong> : ouvrir les deux sandboxes, POC d&#39;envoi d&#39;agrégats B2C (format XML par décades) — valide notre modèle de données spec 12.</li><li><strong>Phase 2 (avant fin T1 2027)</strong> : contractualiser avec la PA retenue (négociation tarif volume : N marchands × 3 transmissions/mois).</li><li>Si des clients GE/ETI signent avant : traiter leur e-reporting en priorité (obligation déjà en vigueur pour eux).</li></ol><h2 id="recapitulatif-des-prochaines-actions-par-ordre-de-priorite" tabindex="-1">Récapitulatif des prochaines actions (par ordre de priorité) <a class="header-anchor" href="#recapitulatif-des-prochaines-actions-par-ordre-de-priorite" aria-label="Permalink to &quot;Récapitulatif des prochaines actions (par ordre de priorité)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Action</th><th>Qui</th><th>Quand</th></tr></thead><tbody><tr><td>1</td><td>Inscription fournisseur NACEF depuis une connexion tunisienne + téléchargement du cahier des charges</td><td>Toi / proche en Tunisie</td><td>Cette semaine</td></tr><tr><td>2</td><td>Appel DGI (+216 81 100 400) : processus, frais, délais d&#39;homologation</td><td>Toi</td><td>Cette semaine</td></tr><tr><td>3</td><td>Email Flouci (dev-support@) pour la clé QR Payments</td><td>Toi</td><td>Cette semaine</td></tr><tr><td>4</td><td>Compte sandbox Konnect + premier test API</td><td>Dev</td><td>Dès le scaffold</td></tr><tr><td>5</td><td>Sandboxes iopole + B2Brouter, POC e-reporting B2C</td><td>Dev</td><td>Phase 1-2</td></tr><tr><td>6</td><td>Réviser la spec 15 avec le cahier des charges NACEF réel</td><td>Nous</td><td>Dès réception</td></tr><tr><td>7</td><td>Contrat PA France</td><td>Toi</td><td>Avant fin T1 2027</td></tr></tbody></table></div>',1)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
